class Queue:
    def __init__(self):
        self.items = {}
        self.serial = 0

    def enqueue(self, key, payload):
        if key not in self.items:
            self.items[key] = {
                "payload": payload,
                "done": False,
                "token": None,
                "expires_at": None,
            }

    def claim(self, key, now=0, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        item = self.items.get(key)
        if item is None or item["done"]:
            return None
        if item["token"] is not None:
            expires_at = item["expires_at"]
            if expires_at is None or now < expires_at:
                return None
        self.serial += 1
        item["token"] = self.serial
        item["expires_at"] = None if ttl is None else now + ttl
        return (item["payload"], item["token"])

    def ack(self, key, token):
        item = self.items.get(key)
        if item is None or item["done"] or token is None or item["token"] != token:
            return False
        item["done"] = True
        return True
